// Every /v1 request without a token is 401 until TASK-102 replaces this with Supabase JWT verification.
// Decodes token generated by /auth/login for local and manual testing.
// Tests inject fakeAuth(principal) through createApp({ auth }).
import { AppError, type RequestContext } from '@dsa/contracts';
import type { RequestHandler } from 'express';

export const authPlaceholder: RequestHandler = (req, _res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next(AppError.of('UNAUTHENTICATED', 'Missing or invalid access token.'));
  }

  const rawToken = authHeader.slice(7).trim();
  if (rawToken.startsWith('token_')) {
    try {
      const payloadBase64 = rawToken.slice(6);
      const user = JSON.parse(Buffer.from(payloadBase64, 'base64url').toString('utf-8'));
      (req as unknown as { ctx: RequestContext }).ctx = {
        principal: {
          kind: 'USER',
          id: user.id || 'usr_01JTESTUSER0000000000000000',
          tenantId: user.tenantId || 'ten_01JTESTTENANT00000000000000',
          primaryBranchId: null,
          managedTeamMemberIds: [],
          queueIds: [],
          grants: [
            { code: 'config.manage', scope: 'TENANT', branchIds: [] },
            { code: 'activity.update', scope: 'TENANT', branchIds: [] },
            { code: 'message.send', scope: 'TENANT', branchIds: [] },
          ],
          authTime: null,
        },
        correlationId: (req as unknown as { correlationId?: string }).correlationId ?? 'corr_dev',
        now: new Date(),
        ip: req.ip,
        userAgent: req.get('user-agent'),
      };
      return next();
    } catch {
      return next(AppError.of('UNAUTHENTICATED', 'Invalid access token.'));
    }
  }

  return next(AppError.of('UNAUTHENTICATED', 'Missing or invalid access token.'));
};
